package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;import java.io.*;import org.w3c.dom.*;
/** Only original private drafts may be explicitly closed/discarded; KML needs MainSave. */
final class GeometryCloseGuardChecks {
 final GeometryCloseConfirmationChecks b;final MapAndroidChecks m;final MapVertexConfirmationChecks c;final GeometryConfirmationChecks g;final ManagerVisualChecks v;final ManagerRotationChecks r;
 GeometryCloseGuardChecks(GeometryCloseConfirmationChecks b){this.b=b;m=b.m;c=b.c;g=b.g;v=b.v;r=b.r;}
 void open(long id)throws Exception{new MapUndoGuardChecks(new MapUndoRotationChecks(m)).open(id,true);m.dragVertex(1,14,8,false);m.check(g.key().equals("0.1")&&(Integer)m.call(m.vertexState(),"undoCount",new Class[]{})==1,"close guard real drag owns nonzero part");b.prompt();}
 void rotate(int direction)throws Exception{Activity old=m.activity;c.p.rotate(direction);m.check(old!=m.activity&&old.isDestroyed(),"close guard actual destroyed/recreate");if(m.editorField("mapCanvas")!=null){c.settledMapLayout();m.check(c.layout().getBoolean("interactiveThreshold"),"close guard original80px map threshold");}}
 void identity(long id,String raw,String token,String session)throws Exception{b.identity(id,session,"0.1",token,(String)m.staticCall("VertexEditDraft","stamp",new Class[]{String.class},raw));}
 byte[] draftBytes(long id)throws Exception{StringBuilder h=new StringBuilder();for(byte x:java.security.MessageDigest.getInstance("SHA-256").digest("point".getBytes("UTF-8")))h.append(String.format(java.util.Locale.US,"%02x",x&255));File f=new File(new File(m.getTargetContext().getFilesDir(),"geometry-drafts"),"g_"+id+"_"+h+".draft");if(!f.exists())return null;ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(f)){byte[] buf=new byte[4096];int n;while((n=in.read(buf))!=-1)out.write(buf,0,n);}return out.toByteArray();}
 void mainChanged(Object store)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);String raw=m.editorText(),token=(String)m.editorField("expected"),session=(String)m.editorField("VERTEX_SESSION");rotate(UiAutomation.ROTATION_FREEZE_90);String newer=raw+"\n23.5 13.5 33.5";EditText field=(EditText)m.editorField("input");m.runOnMainSync(()->field.setText(newer));m.click("Сохранить черновик");m.check(b.present()&&!b.enabled()&&!m.activity.isFinishing()&&m.editorText().equals(newer),"old close cannot save/discard newer main or close Activity");identity(id,raw,token,session);g.unchanged(store,id,xml,assets);rotate(UiAutomation.ROTATION_FREEZE_0);m.check(b.present()&&!b.enabled()&&m.editorText().equals(newer),"blocked close does not rebind newer raw on reverse recreate");identity(id,raw,token,session);b.snapshot("main-changed");m.click("Продолжить редактирование");g.unchanged(store,id,xml,assets);v.emit("GEOMETRY_CLOSE_MAIN_CHANGED PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void stale(Object store,boolean before)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false);try{Object doc=r.load(store,id);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);String raw=m.editorText(),token=(String)m.editorField("expected"),session=(String)m.editorField("VERTEX_SESSION");MapPartChoiceGuardChecks change=new MapPartChoiceGuardChecks(new MapPartConfirmationChecks(m));if(before)change.change(store,id,false,false);rotate(UiAutomation.ROTATION_FREEZE_90);if(!before)change.change(store,id,false,false);rotate(UiAutomation.ROTATION_FREEZE_0);identity(id,raw,token,session);byte[] xml=r.xml(r.load(store,id));m.check(b.present()&&b.enabled()&&m.editorText().equals(raw),"stale KML keeps original expected token and private-only intention");b.snapshot(before?"stale-before":"stale-after");m.click("Продолжить редактирование");g.unchanged(store,id,xml,assets);b.prompt();m.click(before?"Сохранить черновик":"Отменить ввод");b.closed();g.unchanged(store,id,xml,assets);if(!before)m.check(draftBytes(id)==null,"explicit stale discard is not recreated by closing lifecycle");b.launch(id);if(!g.key().equals("0.1")){m.clickDescription("Выбор геометрии и контура");m.click("Геометрия 0.1 · LineString");m.geometryReady();}m.check(m.editorText().equals(before?raw:"24 14 34\n25 15 35\n26 16 36"),"explicit stale local save/discard never overwrites newer KML");g.unchanged(store,id,xml,assets);if(before){m.check(token.equals(m.editorField("expected")),"SaveDraft keeps original expected editing token after fresh launch");m.click("Сохранить");m.geometryReady();m.waitText("Не удалось сохранить");m.check(m.editorText().equals(raw),"separate stale MainSave keeps local raw and refuses newer KML overwrite");g.unchanged(store,id,xml,assets);}v.emit("GEOMETRY_CLOSE_STALE before="+before+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void foreign(Object store,boolean project)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false),other=-1;try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));long target=id;if(project){Object copy=r.parse(xml);m.assets(copy).putAll(assets);other=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},copy,"QA_CLOSE_FOREIGN");target=other;}open(id);final long pid=target;String feature=project?"point":"other";m.runOnMainSync(()->m.activity.setIntent(new Intent(m.activity.getIntent()).putExtra("project",pid).putExtra("feature",feature)));for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){rotate(direction);m.check((Long)m.editorField("project")==target&&feature.equals(m.editorField("featureId"))&&m.editorField("closeDraft")==null&&!b.present()&&m.editorField("mapCanvas")==null&&m.editorField("mapState")==null&&m.editorText().equals(project?"8 9 7":"22 12 32"),"foreign owner/feature never adopts close intent/raw/map/Undo");g.unchanged(store,id,xml,assets);g.unchanged(store,target,xml,assets);}b.snapshot(project?"foreign-project":"foreign-feature");v.emit("GEOMETRY_CLOSE_FOREIGN project="+project+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);if(other>0)m.call(store,"remove",new Class[]{long.class},other);}}
 void replacement(Object store,boolean discard)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);String raw=m.editorText(),token=(String)m.editorField("expected"),session=(String)m.editorField("VERTEX_SESSION");rotate(UiAutomation.ROTATION_FREEZE_90);String newer=raw+"\n24.5 14.5 34.5";Object replacement=m.owned("GeometryDraft").getConstructor(String.class,String.class,String.class,boolean.class).newInstance("0.1",token,newer,false);m.call(replacement,"save",new Class[]{File.class,long.class,String.class},new File(m.getTargetContext().getFilesDir(),"geometry-drafts"),id,"point");byte[] bytes=draftBytes(id);m.click(discard?"Отменить ввод":"Сохранить черновик");m.check(b.present()&&!b.enabled()&&!m.activity.isFinishing()&&m.editorText().equals(raw)&&Arrays.equals(bytes,draftBytes(id)),"close refuses replaced draft without deleting/overwriting it");identity(id,raw,token,session);g.unchanged(store,id,xml,assets);rotate(UiAutomation.ROTATION_FREEZE_0);m.check(b.present()&&!b.enabled()&&m.editorText().equals(newer)&&Arrays.equals(bytes,draftBytes(id)),"reverse recreate preserves exact newer private file and blocks original stamp");identity(id,raw,token,session);b.snapshot(discard?"replacement-discard":"replacement-save");m.click("Продолжить редактирование");g.unchanged(store,id,xml,assets);v.emit("GEOMETRY_CLOSE_REPLACEMENT discard="+discard+" PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void cancel(Object store)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);String raw=m.editorText();m.click("Продолжить редактирование");for(int direction:new int[]{UiAutomation.ROTATION_FREEZE_90,UiAutomation.ROTATION_FREEZE_0}){rotate(direction);m.check(!b.present()&&m.editorField("closeDraft")==null&&g.key().equals("0.1")&&m.editorText().equals(raw)&&(Integer)m.call(m.vertexState(),"undoCount",new Class[]{})==1,"cancelled close never reappears/discards private edit");g.unchanged(store,id,xml,assets);}b.snapshot("cancel-ghost");v.emit("GEOMETRY_CLOSE_CANCEL_GHOST PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void save(Object store)throws Exception{long id=new VertexInsertionChecks(m).fixture(store,false);try{Object doc=r.load(store,id);byte[] xml=r.xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));open(id);String raw=m.editorText();rotate(UiAutomation.ROTATION_FREEZE_90);m.click("Продолжить редактирование");rotate(UiAutomation.ROTATION_FREEZE_0);g.unchanged(store,id,xml,assets);Object expected=r.parse(xml);Element line=(Element)m.element(expected,"point").getElementsByTagNameNS("*","LineString").item(0);StringBuilder coords=new StringBuilder();for(String row:raw.split("\\n")){String[] xyz=row.trim().split("\\s+");if(coords.length()>0)coords.append(' ');coords.append(Double.parseDouble(xyz[1])).append(',').append(Double.parseDouble(xyz[0])).append(',').append(Double.parseDouble(xyz[2]));}((Element)line.getElementsByTagNameNS("*","coordinates").item(0)).setTextContent(coords.toString());m.click("Сохранить");m.geometryReady();m.mapEditorReady();m.check(m.treeToken(expected).equals(m.treeToken(r.load(store,id))),"only separate MainSave changes selected LineString preserving all other DOM");r.sameAssets(r.load(store,id),assets);b.snapshot("main-saved");v.emit("GEOMETRY_CLOSE_MAIN_SAVE PASS");}finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}}
 void run()throws Exception{int requests=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(m.getTargetContext());try{mainChanged(store);stale(store,true);stale(store,false);foreign(store,true);foreign(store,false);replacement(store,false);replacement(store,true);cancel(store);save(store);m.check(m.requests.get()==requests,"guarded local close actions stay local");}finally{v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);m.call(store,"close",new Class[]{});}}
}
